// Reads the generated canette.yaml JSON Schemas (apps/docs/public/schema,
// generated by tools/canette-schema). Imported as a Bun macro, like loadDocs,
// so the compiled API binary carries the schemas of the release it was built
// from.

import { existsSync, readFileSync } from "fs"
import { join } from "path"

export const SCHEMA_FILES = ["canette.json", "canette-template.json"] as const
export type SchemaFile = (typeof SCHEMA_FILES)[number]

const DEFAULT_SCHEMA_DIR = join(import.meta.dir, "../../../docs/public/schema")

/** Raw JSON text per schema file. Throws when a file is missing or not JSON, so the build fails. */
export function loadSchemas(dir: string = DEFAULT_SCHEMA_DIR): Record<SchemaFile, string> {
  const out = {} as Record<SchemaFile, string>
  for (const file of SCHEMA_FILES) {
    const path = join(dir, file)
    if (!existsSync(path)) fail(`${path} not found`)
    const text = readFileSync(path, "utf8")
    try {
      JSON.parse(text)
    } catch {
      fail(`${path} is not valid JSON`)
    }
    out[file] = text
  }
  return out
}

function fail(reason: string): never {
  const message = `Cannot bundle the canette.yaml JSON Schemas for the MCP server: ${reason}. Run "bun run generate:schema" and copy apps/docs/public/schema into the build (see apps/api/Dockerfile).`
  // Bun replaces an error thrown inside a macro with a generic message, so print the reason first.
  console.error(message)
  throw new Error(message)
}
